<script setup lang="ts">
import { ElDialog } from 'element-plus'
import { onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { applications, saveApplication, workspaceError, type Application, type WorkspaceMeta } from '../../api/workspace'
import { accountAction, accountState, hasAccountPassword, accountSource, listAccounts, revealAccount, saveAccount, type Account, type AccountInput } from '../../api/accounts'
const props=defineProps<{clusterId:string;meta:WorkspaceMeta;actorId:string;refreshVersion:number;openVersion?:number;applicationId?:string;applicationName?:string;accountId?:string}>()
const emit=defineEmits<{clearFilter:[]}>()
const rows=ref<Account[]>([]), apps=ref<Application[]>([]), total=shallowRef(0),page=shallowRef(1),busy=shallowRef(false),error=shallowRef(''),editing=shallowRef(false),secret=shallowRef(''),secretAccount=shallowRef(''),confirmed=shallowRef(false)
const form=ref<AccountInput>({mode:'create',application_id:'',username:'',password:''})
const newApp=ref({name:'',owner:'',description:''}),accessMode=shallowRef('produce'),topics=shallowRef(''),group=shallowRef(''),creatingApp=shallowRef(false)
const revealingId=shallowRef(''),copyNotice=shallowRef('')
let secretTimer:ReturnType<typeof globalThis.setTimeout>|undefined
let epoch=0,secretEpoch=0
function changeMode(){form.value.password='';form.value.username='';form.value.request_id=globalThis.crypto.randomUUID()}
function clearSecret(){++secretEpoch;if(secretTimer)globalThis.clearTimeout(secretTimer);secretTimer=undefined;secret.value='';secretAccount.value='';copyNotice.value='';revealingId.value=''}
function accountMatches(account:Account){return account.id===props.accountId||!!props.accountId?.startsWith('external:')&&account.username===props.accountId.slice(9)}
async function load(){const token=++epoch;busy.value=true;error.value='';try{let [accounts,applicationsPage]=await Promise.all([listAccounts(props.clusterId,page.value,props.applicationId),applications(props.clusterId)]);if(token!==epoch)return;
if(props.accountId){let next=1;while(!accounts.items.some(accountMatches)&&accounts.items.length&&next*(accounts.page_size||20)<accounts.total){accounts=await listAccounts(props.clusterId,++next,props.applicationId);if(token!==epoch)return}accounts={...accounts,items:accounts.items.filter(accountMatches),total:accounts.items.some(accountMatches)?1:0};if(!accounts.items.length)error.value='账号不存在或已移除，请返回账号列表'}
if(token===epoch){rows.value=accounts.items;total.value=accounts.total;apps.value=applicationsPage.items}}catch(e){if(token===epoch)error.value=workspaceError(e)}finally{if(token===epoch)busy.value=false}}
async function save(){
 if(busy.value||!confirmed.value)return
 const token=epoch;busy.value=true;error.value='';const input={...form.value};form.value.password=''
 try{
  if(creatingApp.value){const app=await saveApplication(props.clusterId,{...newApp.value,principal:'',request_id:input.request_id});if(token!==epoch)return;input.application_id=app.id;form.value.application_id=app.id;creatingApp.value=false}
  if(input.mode==='create'){input.access_mode=accessMode.value;input.topics=[...new Set(topics.value.split(/[\n,]/).map(x=>x.trim()).filter(Boolean))].map(name=>({name,pattern_type:'LITERAL' as const}));if(accessMode.value!=='produce')input.group={name:group.value,pattern_type:'LITERAL'}}
  await saveAccount(props.clusterId,input);if(token===epoch){editing.value=false;await load()}
 }catch(e){if(token===epoch)error.value=workspaceError(e)}finally{input.password='';if(token===epoch)busy.value=false}
}
async function transition(account:Account,action:'approve'|'execute'){if(busy.value||!confirmed.value)return;const token=epoch;busy.value=true;error.value='';try{await accountAction(props.clusterId,account,action);if(token===epoch)await load()}catch(e){if(token===epoch)error.value=workspaceError(e)}finally{if(token===epoch)busy.value=false}}
async function reveal(account:Account){if(!props.meta.permissions.credentials_read||!hasAccountPassword(account)||revealingId.value)return;clearSecret();revealingId.value=account.id;const token=secretEpoch,cluster=props.clusterId;try{const result=await revealAccount(cluster,account);if(token===secretEpoch&&cluster===props.clusterId){secret.value=result.password;secretAccount.value=account.username;secretTimer=globalThis.setTimeout(()=>{if(token===secretEpoch)clearSecret()},30000)}}catch(e){if(token===secretEpoch)error.value=workspaceError(e)}finally{if(token===secretEpoch)revealingId.value=''}}
function open(){clearSecret();form.value={request_id:globalThis.crypto.randomUUID(),mode:'create',application_id:'',username:'',password:''};confirmed.value=false;editing.value=true;topics.value='';group.value='';creatingApp.value=false}
watch(()=>[props.clusterId,props.applicationId,props.accountId],()=>{clearSecret();form.value.password='';editing.value=false;page.value=1;rows.value=[];void load()},{immediate:true})
watch(()=>props.refreshVersion,()=>{clearSecret();void load()})
watch(()=>props.openVersion,value=>{if(value){open();creatingApp.value=true}},{immediate:true})
onBeforeUnmount(()=>{++epoch;clearSecret();form.value.password=''})
watch(()=>props.meta.permissions.credentials_read,allowed=>{if(!allowed)clearSecret()})
function importPassword(account:Account){open();form.value={request_id:globalThis.crypto.randomUUID(),mode:'import',username:account.username,password:'',application_id:props.applicationId??account.application_ids[0]??''}}
async function copyPassword(){if(!secret.value)return;try{await globalThis.navigator.clipboard.writeText(secret.value);copyNotice.value='已复制'}catch{copyNotice.value='复制失败，请手动复制'}}
function passwordReason(account:Account){return !props.meta.permissions.credentials_read?'没有查看密码的权限':!hasAccountPassword(account)?'未保存密码':''}
const appNames=(account:Account)=>account.application_ids.map(id=>apps.value.find(app=>app.id===id)?.name??'未加载的应用').join('、')||'未关联应用'
</script>
<template>
  <section class="account-workspace">
    <div class="panel">
      <div class="panel-header"><div><h2>Kafka 账号</h2></div><div class="account-actions"><button :disabled="busy" @click="clearSecret();load()">刷新</button><button v-if="meta.permissions.account_manage" v-show="!accountId" data-new-account class="button-primary" :disabled="busy" @click="open">新建 / 录入账号</button></div></div>
      <p v-if="applicationName" class="account-message">应用：{{ applicationName }} <button @click="emit('clearFilter')">查看全部账号</button></p>
      <p v-if="error" role="alert" class="error account-message">{{ error }}</p>
      <form v-if="editing" data-account-form class="account-editor" @submit.prevent="save"><h3>应用、账号与所需权限</h3><label class="account-confirm"><input v-model="creatingApp" type="checkbox">同时添加新应用</label><template v-if="creatingApp"><label>应用名称<input v-model="newApp.name" name="new_application_name" required maxlength="128"></label><label>负责人<input v-model="newApp.owner" name="new_application_owner" required maxlength="128"></label></template><label v-if="!creatingApp">所属应用{{ form.mode==='import'?'（可选）':'' }}<select v-model="form.application_id" :required="form.mode!=='import'" name="account_application"><option :disabled="form.mode!=='import'" value="">{{ form.mode==='import'?'暂不关联应用':'请选择应用' }}</option><option v-for="app in apps" :key="app.id" :value="app.id">{{ app.name }}</option></select></label><label>接入方式<select v-model="form.mode" name="account_mode" @change="changeMode"><option value="create">自动生成账号和密码</option><option value="import">录入已有账号和密码</option><option value="reference">仅关联已有账号</option></select></label><label v-if="form.mode!=='create'">已有用户名<input v-model="form.username" required name="account_username" maxlength="128" autocomplete="off"></label><label v-if="form.mode==='import'">已有密码<input v-model="form.password" required name="account_password" type="password" autocomplete="new-password" maxlength="1024"></label><template v-if="form.mode==='create'"><label>用途<select v-model="accessMode" name="account_access_mode"><option value="produce">生产消息</option><option value="consume">消费消息</option><option value="produce_consume">生产与消费</option></select></label><label>Topic 精确名称<textarea v-model="topics" name="account_topics" required rows="2" placeholder="多个名称用逗号或换行分隔" /></label><label v-if="accessMode!=='produce'">消费组<input v-model="group" name="account_group" required></label></template><p class="helper-text">{{ form.mode==='create'?'平台生成随机用户名及密码，批准后在 Kafka 创建。':'录入不会修改 Kafka 密码或既有 ACL。' }}</p><label class="account-confirm"><input v-model="confirmed" type="checkbox">我已确认账号来源与应用关联</label><div class="account-actions"><button type="button" @click="editing=false;form.password=''">取消</button><button class="button-primary" :disabled="busy||!confirmed">{{ form.mode==='create'?'创建账号':'保存账号' }}</button></div></form>
      <div class="table-scroll"><table class="data-table account-table"><thead><tr><th>Kafka 账号</th><th>关联应用</th><th>认证状态</th><th>密码</th><th>操作</th></tr></thead><tbody><tr v-for="account in rows" :key="account.id||account.username"><td data-label="账号"><router-link v-if="!accountId" :to="`/kafka/clusters/${encodeURIComponent(clusterId)}/accounts/${encodeURIComponent(account.id)}`">{{ account.username }}</router-link><strong v-else>{{ account.username }}</strong><small>{{ accountSource(account.source) }}</small></td><td data-label="应用">{{ appNames(account) }}</td><td data-label="认证">{{ account.mechanism }}<small>{{ accountState(account.observation) }}</small><small v-if="account.operation">{{ accountState(account.operation.status) }} {{ account.operation.code||'' }}</small><details v-if="account.operation?.rules?.length"><summary>核对权限与执行步骤</summary><p v-for="(rule,index) in account.operation.rules" :key="index">{{ rule.resource_type }} · {{ rule.resource_name }} · {{ rule.pattern_type }} · {{ rule.operation }} / {{ rule.permission }} · {{ rule.host }}</p><p v-for="(result,index) in account.operation.results" :key="index">{{ result.rule?.resource_name || account.username }} · {{ result.state }} {{ result.code || '' }}</p></details></td><td data-label="密码" class="account-password-cell"><span>{{ hasAccountPassword(account)?'已保存密码':'未保存密码' }}</span><button data-reveal-account :disabled="busy||!!revealingId||!!passwordReason(account)" :title="passwordReason(account)||'查看密码'" @click="reveal(account)">{{ revealingId===account.id?'读取中…':'查看密码' }}</button><small v-if="!meta.permissions.credentials_read">{{ passwordReason(account) }}</small><button v-if="meta.permissions.account_manage&&!hasAccountPassword(account)" data-import-password :disabled="busy||account.mechanism!=='SCRAM-SHA-256'" @click="importPassword(account)">录入密码</button></td><td data-label="操作"><div class="account-actions"><button v-if="account.operation?.status==='pending_approval'&&account.operation.created_by!==actorId" :disabled="busy||!confirmed" @click="transition(account,'approve')">审批通过</button><button v-if="account.operation?.status==='approved'" :disabled="busy||!confirmed||!meta.write_enabled" @click="transition(account,'execute')">创建账号</button></div></td></tr><tr v-if="!rows.length"><td colspan="5" class="account-empty">{{ busy?'正在查询账号…':'暂无可管理账号' }}</td></tr></tbody></table></div><div v-if="!accountId" class="account-pagination"><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 个账号</span><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button><label class="account-confirm"><input v-model="confirmed" type="checkbox">已核对待执行账号与关联应用</label></div>
    </div>
    <ElDialog :model-value="!!secret" title="账号密码" width="min(480px, 94vw)" destroy-on-close @close="clearSecret"><div v-if="secret" class="password-dialog"><strong>{{ secretAccount }}</strong><input :value="secret" aria-label="账号密码" readonly autocomplete="off" spellcheck="false"><p>30 秒后自动关闭</p><p v-if="copyNotice" role="status">{{ copyNotice }}</p><div class="account-actions"><button class="button-primary" @click="copyPassword">复制密码</button><button @click="clearSecret">关闭</button></div></div></ElDialog>
  </section>
</template>
<style scoped>
.password-dialog{display:grid;gap:16px}.password-dialog p{font-size:12px;color:#64748b;margin:0}.password-dialog input{width:100%;font-family:monospace}.account-password-cell button{display:block;margin-top:8px}.account-password-cell small{max-width:160px}.account-workspace{display:grid;gap:18px}.account-actions{display:flex;gap:8px;flex-wrap:wrap}.account-message,.account-editor,.account-secret{padding:20px}.account-editor{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;border-top:1px solid #e5ebf3;background:#f8fafc}.account-editor h3,.account-editor p{grid-column:1/-1;margin:0}.account-editor label{display:grid;gap:7px;font-size:12px;color:#526176}.account-confirm{display:flex!important;align-items:center;gap:8px;font-size:12px}.account-pagination{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:16px 20px;font-size:12px;color:#64748b}.account-empty{text-align:center;padding:28px}.data-table small{display:block;color:#64748b;margin-top:5px}.account-secret code{display:block;padding:16px;background:#f1f5f9;overflow-wrap:anywhere;margin-bottom:12px}.account-secret p{font-size:12px;color:#64748b}@media(max-width:640px){.account-workspace .account-table{display:block;min-width:0}.account-table thead{display:none}.account-table tbody,.account-table tr{display:block}.account-table tr{border-bottom:1px solid #dce5ef;padding:8px 0}.account-table td{display:block;border:0;padding:8px 16px;overflow-wrap:anywhere}.account-table td::before{content:attr(data-label);display:inline-block;min-width:44px;margin-right:8px;font-weight:500;color:#64748b}.account-password-cell button{display:inline-block;margin-left:8px}.account-editor{grid-template-columns:1fr}}
</style>
